Method.Implementation:
	#dim tSC As %Status
	set tSC = $$$OK
	Try {

		 set tst = ##class(ITFCOMMON.SrcCtrl.CreateDeploymentFiles).%New()
  		 set retStr = tst.CreateDeploymentFiles( Component, NameSp, userNm, passwd)
  		 // Write !, "CreateDeploymentFiles exit Stat: " _ tSC
	}
	Catch exp {
		set fault=..MakeFault($$$FAULTServer,"Error in calling CreateDeploymentFiles " _ exp.Name)
		Do ..ReturnFault(fault)

	}

  	return retStr
